class Result(object):
    '''The result of a parse() or search() operation.

    The fixed attribute holds the tuple of positional field values extracted
    from the string in order.
    The named attribute holds the dictionary of named fields extracted from
    the string.
    The spans attribute holds a dict mapping names and indices to 2-tuple
    ranges of where the match occurred in the input.
    '''

    def __init__(self, fixed, named, spans):
        self.fixed = fixed
        self.named = named
        self.spans = spans

    def __getitem__(self, item):
        if isinstance(item, slice):
            return self.fixed[item]
        if isinstance(item, int):
            return self.fixed[item]
        return self.named[item]

    def __contains__(self, value):
        """Check if value exists in the parsed results."""
        return value in self.fixed or value in self.named.values()

    def __repr__(self):
        return '<%s %r %r>' % (self.__class__.__name__, self.fixed,
            self.named)

